SELECT pp.primary_key as collaborateMaterial, pp.unity_no, pp.product_part_sign as name, pp.model, SUM(COALESCE(inboundItem.inbound_quantity, 0)) AS inboundQuantity, SUM(COALESCE(inboundItem.order_quantity, 0)) - SUM(COALESCE(inboundItem.inbound_quantity, 0)) AS difference FROM ${collaborateInboundItemTableName} inboundItem LEFT JOIN ${productPartTableName} pp ON inboundItem.collaborate_material = pp.primary_key WHERE inboundItem.enterprise_code = #{enterpriseCode} and inboundItem.delete_flag = false
AND inboundItem.create_time >= #{requestData.startTime}
AND inboundItem.create_time <= #{requestData.endTime}
GROUP BY pp.primary_key, pp.unity_no, pp.product_part_sign, pp.model order by difference desc

